import numpy as np, time
from rcb_hb import Session
s=Session('window',instance='/app/instance.npz'); s.reset(); m,d=s.low.model,s.low.data
lo,hi=m.actuator_ctrlrange[:,0],m.actuator_ctrlrange[:,1]
qadr=np.array([m.jnt_qposadr[int(m.actuator_trnid[i,0])] for i in range(m.nu)])
name_to_act={m.actuator(i).name:i for i in range(m.nu)}
bodyid=next(i for i in range(m.nbody) if m.body(i).name=='window_wiping_tool')
headsite=next(i for i in range(m.nsite) if m.site(i).name=='head')
handids=[next(i for i in range(m.nsite) if m.site(i).name==n) for n in ('left_hand','right_hand')]
contactsites=[next(i for i in range(m.nsite) if m.site(i).name==f'wipe_contact_site_{x}') for x in 'abcde']
init_head=d.site_xpos[headsite].copy();
def ctrl(i,x): return np.clip(2*(x-lo[i])/(hi[i]-lo[i])-1,-1,1)
base=np.zeros(m.nu)
for i in range(21): base[i]=ctrl(i,d.qpos[qadr[i]])
for i in (2,7): base[i]=ctrl(i,.5)
for i in (3,8): base[i]=ctrl(i,.2)
for i in (4,9): base[i]=ctrl(i,-.8)
for i in (11,16): base[i]=ctrl(i,.2)
base[23:41]=.85;base[43:61]=.85

def run(L):
 # params dict L: start, per, amp_p, center_p, amp_e, center_e, phase_e, amp_r, center_r, amp_roll, phase_roll
 s.reset(); d=s.low.data; a=base.copy(); rows=[]
 for t in range(1000):
  if t>=100:
   fade=min(1,(t-100)/30)
   for i,x in zip((12,13,17,18),(-.32,-.32,.32,.32)): a[i]=ctrl(i,x*fade)
  if t>=L.get('knees',500):
   for i in (3,8):a[i]=ctrl(i,0)
  if t>=L['start']:
   x=2*np.pi*(t-L['start'])/L['per']+L.get('phase',1.5*np.pi)
   center=L.get('center',.2)-L.get('shift',.1)*np.clip((t-L.get('shiftstart',400))/L.get('shiftlen',50),0,1)
   a[11]=ctrl(11,center+L.get('ap',.3)*np.sin(x))
   a[16]=ctrl(16,L.get('rcenter',center))
   if L.get('ae',0): a[14]=ctrl(14,L.get('ecenter',-.6)+L['ae']*np.sin(x+L.get('ephase',0)))
   if L.get('ar',0): a[19]=ctrl(19,L.get('rcen',-.6)+L['ar']*np.sin(x+L.get('rphase',0)))
   if L.get('aroll',0): a[12]=ctrl(12,-.32+L['aroll']*np.sin(x+L.get('rollphase',0)))
  _,_,done=s.step(a)
  # exact pane vs wiper collision geom
  ct=0
  for j in range(d.ncon):
   p=d.contact[j]
   if p.geom1==184 and p.geom2 in (189,190) or p.geom2==184 and p.geom1 in (189,190):ct=1;break
  pos=d.site_xpos[contactsites].mean(axis=0).copy()
  hands=np.array([np.linalg.norm(d.site_xpos[h]-d.xpos[bodyid]) for h in handids])
  rows.append([ct,*pos,*hands,d.site_xpos[headsite,0],d.site_xpos[headsite,1],d.site_xpos[headsite,2],d.qpos[qadr[11]],d.qpos[qadr[14]],d.qpos[qadr[16]],d.qpos[qadr[19]],d.qvel[qadr[11]],d.qvel[qadr[14]],d.qvel[qadr[16]],d.qvel[qadr[19]],d.qpos[2],d.qpos[3]])
  if done:break
 r=np.asarray(rows); c=r[:,0].astype(bool); z=r[:,3]; vz=np.r_[0,np.abs(np.diff(z))*50]; cv=vz[c].mean() if c.any() else 0
 # proxy optimize contact and speed while all-step survival and hands near. More focus on staying pane and moving.
 h=r[:,4:6].mean(axis=1)
 # means (pane, cv, contact weighted speed, hand distance, duration, range)
 return {'n':len(r),'pane':c.mean(),'cv':cv,'cvsum':(vz*c).sum()/1000,'hands':h.mean(),'hcont':h[c].mean() if c.any() else 0,'zrange':np.ptp(z),'headx':r[:,6].mean(),'z':np.mean(z),'end':r[-1,3], 'score': c.mean()*2 + (vz*c).sum()/1000 + max(0,1-h.mean()) + len(r)/1000, 'rows':r}

if __name__=='__main__':
 tests=[]
 for per in (60,80,100,120,150):
  for ap in (.25,.35,.45): tests.append(dict(start=250,per=per,ap=ap,center=.2,shift=.1))
 for ae in (.15,.25,.35):
  for ph in (0,np.pi/2,np.pi,3*np.pi/2): tests.append(dict(start=250,per=100,ap=.3,center=.2,shift=.1,ae=ae,ephase=ph))
 for start in (150,200,300): tests.append(dict(start=start,per=100,ap=.3,center=.2,shift=.1))
 out=[]
 for i,p in enumerate(tests):
  st=time.time(); r=run(p); out.append((r['score'],p,r)); print(i,round(time.time()-st,2),p,{k:round(r[k],3) for k in ('n','pane','cv','cvsum','hands','hcont','zrange','headx','score')},flush=True)
 print('\nTOP')
 for score,p,r in sorted(out,key=lambda x:x[0],reverse=True)[:15]: print(round(score,3),p, {k:round(r[k],3) for k in ('pane','cv','cvsum','hands','hcont','zrange','n')})
